import fs from 'fs';
import path from 'path';

const secretPatterns = [
  /api[_-]?key/i,
  /secret/i,
  /token/i,
  /-----BEGIN PRIVATE KEY-----/,
  /AWS_ACCESS_KEY_ID/,
  /AWS_SECRET_ACCESS_KEY/,
  /ghp_[A-Za-z0-9]{36}/,
  /glpat-[A-Za-z0-9\\-]{20,}/,
  /sk_live_[A-Za-z0-9]{20,}/
];

function loadAllowlist(): string[] {
  const file = '.gitcli-scan-allowlist';
  if (!fs.existsSync(file)) return [];
  return fs.readFileSync(file, 'utf8').split('\\n').filter(Boolean);
}

export function scanForSecrets(files: string[]): { file: string; match: string }[] {
  const findings: { file: string; match: string }[] = [];
  const allowlist = loadAllowlist();
  for (const file of files) {
    if (!fs.existsSync(file) || fs.statSync(file).isDirectory()) continue;
    const content = fs.readFileSync(file, 'utf8');
    for (const pattern of secretPatterns) {
      const match = content.match(pattern);
      if (match) {
        const matchVal = match[0];
        if (allowlist.some(entry => matchVal.includes(entry))) continue;
        findings.push({ file: path.relative(process.cwd(), file), match: matchVal });
      }
    }
  }
  return findings;
}
